mapper.select:
SELECT a.role_no AS roleNo , a.pgm_no AS pgmNo , a.comm_btn_auth_yn AS commBtnAuthYn , a.cancel_auth_yn AS cancelAuthYn , a.retrieve_auth_yn AS retrieveAuthYn , a.input_auth_yn AS inputAuthYn , a.ext1_auth_yn AS ext1AuthYn , a.update_auth_yn AS updateAuthYn , a.delete_auth_yn AS deleteAuthYn , a.print_auth_yn AS printAuthYn , a.excel_auth_yn AS excelAuthYn , a.execute_auth_yn AS executeAuthYn , a.indiv_btn_auth_yn AS indivBtnAuthYn FROM fw_role_pgm a WHERE a.sys_id = 'SY' AND a.role_no IN
#{item}
AND a.pgm_no = #{pgmNo} AND (CASE a.valid_dt_yn WHEN 'Y' THEN (CASE WHEN #{today} BETWEEN a.valid_dt_from AND a.valid_dt_to THEN 'true' ELSE 'false' END) ELSE 'true' END) = 'true'
